styl:
.b-new-text-17 .block-empty-12 {  height:12px;line-height:12px;font-size:12px  }
.white-bg.b-new-text-17 {  background:#fff  }
.b-new-text-17 .label, .b-new-text-17 .plys-logo {  display:inline-block  }
.b-new-text-17 .plys-logo {  padding:5px 12px;border:.8px solid #d2d2d2;border-radius:9.6px;vertical-align:middle  }
@media screen and (max-width:600px) {
  .b-new-text-17 .plys-logo {  margin-bottom:10px!important  }
}
.b-new-text-17 .little-big-text {  font-family:Helvetica!important;font-weight:700;font-size:18px;line-height:25px;color:#413e43  }
.b-new-text-17 .image-block {  display:inline-block;width:100%  }
@media screen and (max-width:600px) {
  .b-new-text-17 .image-block {  text-align:center!important  }
}
.b-new-text-17 .disp-ib {  display:inline-block;vertical-align:middle  }
.b-new-text-17 .wb-bw {  word-break:break-word  }
.b-new-text-17 .pr8 {  padding-right:8px  }
@media screen and (max-width:600px) {
  .b-new-text-17 .pr8 {  font-weight:16px!important;line-height:22px!important  }
}
.b-new-text-17 .pt44, .b-new-text-17 .pt45 {  padding-top:44px  }
.br-full-16.b-new-text-17 {  border-radius:16px;-moz-border-radius:16px;-webkit-border-radius:16px  }
.bg-bord-full.b-new-text-17 {  border:1px solid #eae9e9  }
.b-new-text-17 .bb-dash {  border-bottom:1px dashed #c4cbba  }
.b-new-text-17 .pb32 {  padding-bottom:32px  }
.b-new-text-17 .w-hulf {  width:50%!important  }
.b-new-text-17 .w100 {  width:100%!important  }
.b-new-text-17 .w-a {  width:auto!important;vertical-align:middle;padding-bottom:0!important  }
.b-new-text-17 .m-w {  min-width:60px  }
@media screen and (max-width:600px) {
  .b-new-text-17 .m-w {  min-width:40px!important  }
}
.b-new-text-17 .small-image {  width:40px  }
@media screen and (max-width:600px) {
  .b-new-text-17 .small-image {  width:30px!important;max-width:30px!important  }
}
